    categories: ["fuel_cell"],
    sourceUrl: "https://www.fia.com/sites/default/files/ft3.pdf",
    numberPattern: /^(FT3\.5-\d+|FT3-\d+|FT5-\d+)/,
    // Built from a user-provided spreadsheet conversion of the source PDF (fia-xls/ft3.xlsx),
